s2s_df$pred_AM <- AM_gam_all$family$linkinv(pred_AM$fit)
s2s_df$se_AM <- AM_gam_all$family$linkinv(pred_AM$se.fit)

quantile(s2s_df$pred_AM)

s2s_AM <- s2s_df %>% dplyr::select(LON, LAT, pred_AM)

