years <- 2006:2025

all_dates <- do.call(
  c,
  lapply(years, function(y) {
    dates <- seq(
      from = as.Date(sprintf("%d-01-24", y)),
      to   = as.Date(sprintf("%d-01-30", y)),
      by = "day"
    )
    
    rep(dates, each = 10)
  })
)

all_dates

