  #geom_sf(data = area_clip, fill = NA, color = "lightgray", linewidth = 0.5) +
  theme_classic() +
  coord_sf(crs = 32619) +
  labs(fill = "CI width", color = "Presence") +
  ggtitle("Febuary 14 - February 20: Atlantic Mackerel") 
