ocean <- ne_download(
  scale = "large",
  type = "ocean",
  category = "physical",
  returnclass = "sf"
) %>%
  st_transform(4326)

coastline_only <- st_intersection(us_boundary, ocean)

sf_use_s2(TRUE)

atlantic_bbox <- st_as_sfc(st_bbox(c(
  xmin = -82,
  xmax = -60,
  ymin = 34,
  ymax = 45
), crs = st_crs(4326)))

atlantic_coast <- st_intersection(coastline_only, atlantic_bbox) %>%
