us_boundary <- us_land %>%
  st_union() %>%
  st_boundary() %>%
  st_cast("MULTILINESTRING")

ocean <- ne_download(
  scale = "large",
  type = "ocean",
  category = "physical",
  returnclass = "sf"
) %>%
  st_transform(4326)

coastline_only <- st_intersection(us_boundary, ocean)

sf_use_s2(TRUE)

atlantic_bbox <- st_as_sfc(st_bbox(c(
  xmin = -82,
  xmax = -60,
  ymin = 34,
  ymax = 45
), crs = st_crs(4326)))

atlantic_coast <- st_intersection(coastline_only, atlantic_bbox) %>%
  st_simplify(dTolerance = 0.001, preserveTopology = TRUE)

atlantic_coast <- atlantic_coast %>%
  st_collection_extract("LINESTRING") %>%
  st_cast("MULTILINESTRING")


# subtract land from each polygon
grid_water <- st_difference(grid_sf_ll, st_union(us_land))

pal <- colorNumeric(
  palette = scico(100, palette = "roma"),
  domain = c(0, 1),
  na.color = "transparent"
)



AM_plot <- leaflet() %>%
  addProviderTiles("CartoDB.Positron") %>%
  onRender("
    function(el, x) {
      var map = this;
      map.on('click', function(e) {
        L.popup()
          .setLatLng(e.latlng)
          .setContent(
            'Latitude: ' + e.latlng.lat.toFixed(5) +
            '<br>Longitude: ' + e.latlng.lng.toFixed(5)
          )
          .openOn(map);
      });
    }
  ") %>%
  
  # grid_sf polygons
  addPolygons(
    data = grid_water,
    fillColor = ~pal(mean_val),
    fillOpacity = 0.9,
    weight = 0.1,
    color = "black",
    opacity = 0.5,
    popup = ~paste("Encountering probability:", round(mean_val, 3))
  ) %>%
  
  # restriction area (red)
  # addPolygons(
  #   data = restrict_ll,
  #   fillColor = "red",
  #   color = "black",
  #   weight = 1,
  #   fillOpacity = 0.7
  # ) %>%
  
  # # area_clip outline (thick black)
  # addPolylines(
  #   data = area_clip_ll,
  #   color = "black",
  #   weight = 3
  # ) %>%
  
  addLegend(
    pal = pal,
    values = grid_sf_ll$mean_val,
    title = htmltools::HTML("Encountering<br>Probability")
  ) %>%
  
  addScaleBar(
    position = "bottomright",
    options = scaleBarOptions(
      maxWidth = 350,  # length of scale bar in pixels
      metric = TRUE,
      imperial = FALSE,
      updateWhenIdle = TRUE
    ) 
  ) %>%
  onRender("
  function(el, x) {
    var map = this;

    /* ===============================
       HOVER COORDINATES (bottom-left)
       =============================== */
    var coords = L.control({position: 'bottomleft'});
    coords.onAdd = function () {
      this._div = L.DomUtil.create('div', 'leaflet-control');
      this._div.style.background = 'rgba(255,255,255,0.8)';
      this._div.style.padding = '5px';
      this._div.innerHTML = 'Lat: –, Lon: –';
      return this._div;
    };
    coords.addTo(map);

    map.on('mousemove', function(e) {
      coords._div.innerHTML =
        'Lat: ' + e.latlng.lat.toFixed(4) +
        '<br>Lon: ' + e.latlng.lng.toFixed(4);
    });

    /* ===============================
       CENTERED TITLE (top, above zoom)
       =============================== */
    var titleDiv = L.DomUtil.create('div', 'map-title');

    titleDiv.innerHTML = `
      <div style=\"
        position: absolute;
        top: 10px;
        left: 50%;
        transform: translateX(-50%);
        background: rgba(255,255,255,0.9);
        padding: 8px 16px;
        border-radius: 6px;
        font-size: 18px;
        font-weight: bold;
        color: #0b2d49;
        text-align: center;
        white-space: nowrap;
        z-index: 1000;
        box-shadow: 0 2px 6px rgba(0,0,0,0.25);
        pointer-events: none;
      \">
        Atlantic Mackerel
      </div>
    `;

    map.getContainer().appendChild(titleDiv);
  }
") %>%
  addPolylines(
    data = atlantic_coast,
    color = "#1a1a1a",
    weight = 3,
    opacity = 1,
    smoothFactor = 1
  )


library(htmlwidgets)
saveWidget(AM_plot, file = "AM_0411_0417_map.html", selfcontained = TRUE)


