  addProviderTiles("CartoDB.Positron") %>%
  onRender("
    function(el, x) {
      var map = this;
      map.on('click', function(e) {
        L.popup()
          .setLatLng(e.latlng)
          .setContent(
            'Latitude: ' + e.latlng.lat.toFixed(5) +
            '<br>Longitude: ' + e.latlng.lng.toFixed(5)
          )
          .openOn(map);
      });
    }
  ") %>%
  
  # grid_sf polygons
  addPolygons(
    data = grid_water,
    fillColor = ~pal(mean_val),
    fillOpacity = 0.9,
    weight = 0.1,
