# create 0.2 degree template grid
template <- rast(
  xmin = xmin(ECMWF_rt),
  xmax = xmax(ECMWF_rt),
  ymin = ymin(ECMWF_rt),
  ymax = ymax(ECMWF_rt),
  resolution = 0.2,
  crs = crs(ECMWF_rt)
)

# resample to finer grid
